        seen := make(map[string]bool)
        var visit func(name string)
        visit = func(name string) {
                dep, ok := byName[name]
                if !ok {
                        return
                }
                for _, d := range dep.Deps {
                        if !seen[d] {
                                seen[d] = true
                                visit(d)
                        }
                }
        }
        visit(t.Name)

        res := make([]string, 0, len(seen))
        for k := range seen {
                res = append(res, k)
        }
        sort.Strings(res)
        return res
